package httpcache

import "net/http"

// Middleware serves cached responses. It is mounted only in front of the
// public catalogue routes, which answer the same to every caller.
//
// Only GET is cached: every other method changes state or is too rare to be
// worth an entry, and always reaches next.
func Middleware(c *Cache, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			next.ServeHTTP(w, r)
			return
		}
		key := r.URL.RequestURI()
		if e, ok := c.Get(key); ok {
			e.WriteTo(w)
			return
		}
		rec := newRecorder(w)
		next.ServeHTTP(rec, r)
		if rec.status == http.StatusOK {
			c.Set(key, rec.entry())
		}
	})
}
